const first = $input.first().json || {};
const body = first.body || {};
const query = first.query || {};
const zone = 'Europe/Zagreb';
const want = String(body.date || query.date || '');
let day;
if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(want)) day = DateTime.fromISO(want, { zone: zone }).startOf('day');
else day = DateTime.now().setZone(zone).minus({ days: 1 }).startOf('day');
const end = day.plus({ days: 1 });
const hist = day.minus({ days: 6 });
return [{ json: {
  date: day.toISODate(),
  zone: zone,
  oldest: String(Math.floor(day.toSeconds())),
  latest: String(Math.floor(end.toSeconds())),
  history_oldest: String(Math.floor(hist.toSeconds())),
  start_iso: day.toUTC().toISO(),
  end_iso: end.toUTC().toISO(),
  history_start_iso: hist.toUTC().toISO()
} }];

const out = [];
const add = (ch, items) => {
  items.forEach(p => {
    const m = p.json || {};
    if (m.ts && m.reply_count && m.reply_count > 0) out.push({ json: { channel: ch, ts: m.ts } });
  });
};
add('C0ABPEER1MF', $('Slack: errors channel').all());
add('C0A44SWQVHD', $('Slack: incident channel').all());
if (!out.length) out.push({ json: { channel: 'C0A44SWQVHD', ts: '0', skip: true } });
return out;

const w = $('Compute window').first().json;
const oldest = Number(w.oldest);
const latest = Number(w.latest);
const SLACK = 'https://futuremedia-world.enterprise.slack.com/archives/';
const ERR = 'C0ABPEER1MF';
const INC = 'C0A44SWQVHD';
const gaps = [];
const dec = s => String(s || '').split('&amp;').join('&').split('&lt;').join('<').split('&gt;').join('>');
const errText = e => typeof e === 'string' ? e : (e && e.message ? e.message : JSON.stringify(e));
const msgsOf = (nodeName, label) => {
  const all = [];
  $(nodeName).all().forEach(p => {
    const m = p.json || {};
    if (m.error) gaps.push('Slack read failed for ' + label + ': ' + errText(m.error));
    else if (m.ts) all.push(m);
  });
  return all;
};
const errMsgs = msgsOf('Slack: errors channel', '#cs-n8n-automation-errors');
const incMsgs = msgsOf('Slack: incident channel', '#cs-ai-automation-incident');
const link = (ch, ts, threadTs) => SLACK + ch + '/p' + String(ts).split('.').join('') + (threadTs && threadTs !== ts ? '?thread_ts=' + threadTs + '&cid=' + ch : '');
const zag = ts => DateTime.fromSeconds(Number(ts)).setZone('Europe/Zagreb').toFormat('yyyy-MM-dd HH:mm:ss');
const threads = {};
const planned = $('Plan threads').all().map(i => i.json).filter(p => !p.skip);
$('Slack: thread replies').all().forEach(p => {
  const m = p.json || {};
  if (m.error) { if (planned.length) gaps.push('Slack thread read failed: ' + errText(m.error)); return; }
  if (!m.ts || !m.thread_ts || m.ts === m.thread_ts) return;
  if (!threads[m.thread_ts]) threads[m.thread_ts] = [];
  threads[m.thread_ts].push(m);
});
Object.keys(threads).forEach(k => threads[k].sort((a, b) => Number(a.ts) - Number(b.ts)));
const who = m => (m.user_profile && (m.user_profile.real_name || m.user_profile.display_name)) || m.username || (m.bot_profile && m.bot_profile.name) || m.user || 'unknown';
const textOf = m => {
  let t = m.text || '';
  if (!t && m.attachments && m.attachments.length) t = m.attachments.map(a => a.text || a.fallback || '').join(' ');
  return dec(t);
};
const inWin = ts => Number(ts) >= oldest && Number(ts) < latest;
const parseAlert = m => {
  const t = textOf(m);
  if (t.indexOf('CS automation general error') < 0) return null;
  const lines = t.split(String.fromCharCode(10));
  const get = p => { const l = lines.filter(x => x.trim().indexOf(p) === 0)[0]; return l ? l.trim().slice(p.length).trim() : ''; };
  const exm = t.match(/workflow[/]([A-Za-z0-9]+)[/]executions[/]([0-9]+)/);
  const wfName = get('Workflow:');
  const node = get('Node errored:');
  const msg = get('Error message:');
  const bm = wfName.match(/^(.*?) prod - (.*)$/);
  return {
    ts: m.ts,
    time: zag(m.ts),
    workflow_name: wfName,
    brand: bm ? bm[1] : '',
    workflow_type: bm ? bm[2] : wfName,
    workflow_id: exm ? exm[1] : '',
    execution_id: exm ? exm[2] : '',
    errored_node: node,
    error_message: msg,
    is_caller: node.indexOf("Call '") === 0,
    slack_url: link(ERR, m.ts),
    notes: (threads[m.ts] || []).map(r => ({ by: who(r), at: zag(r.ts), text: textOf(r).slice(0, 500) }))
  };
};
const normNode = n => String(n || '').replace(/[0-9]+$/, '').trim();
const sig = a => a.workflow_type + ' | ' + normNode(a.errored_node) + ' | ' + a.error_message;
const allAlerts = errMsgs.map(parseAlert).filter(Boolean);
const winAlerts = allAlerts.filter(a => inWin(a.ts)).sort((x, y) => Number(x.ts) - Number(y.ts));
const histAlerts = allAlerts.filter(a => Number(a.ts) < oldest);
const hist = {};
histAlerts.forEach(a => {
  const s = sig(a);
  if (!hist[s]) hist[s] = { prior_6_days_alerts: 0, first_seen_in_last_7_days: a.time, brands: [], notes: [] };
  const h = hist[s];
  h.prior_6_days_alerts += 1;
  if (a.time < h.first_seen_in_last_7_days) h.first_seen_in_last_7_days = a.time;
  if (a.brand && h.brands.indexOf(a.brand) < 0) h.brands.push(a.brand);
  a.notes.forEach(n => { if (h.notes.length < 5) h.notes.push(Object.assign({ on_alert: a.slack_url }, n)); });
});
const ZRX = /https?:[/][/]([a-z0-9-]+)[.]zendesk[.]com[/]agent[/]tickets[/]([0-9]+)/gi;
const ticketsIn = t => {
  const res = [];
  const rx = new RegExp(ZRX.source, 'gi');
  let m;
  while ((m = rx.exec(String(t))) !== null) res.push({ subdomain: m[1].toLowerCase(), ticket_id: m[2] });
  return res;
};
const reports = [];
incMsgs.forEach(m => {
  if (m.subtype) return;
  const reps = threads[m.ts] || [];
  const newReps = reps.filter(r => inWin(r.ts));
  const parentNew = inWin(m.ts);
  if (!parentNew && !newReps.length) return;
  const text = textOf(m);
  const tk = {};
  ticketsIn(text).forEach(x => { tk[x.subdomain + '/' + x.ticket_id] = x; });
  reps.forEach(r => ticketsIn(textOf(r)).forEach(x => { tk[x.subdomain + '/' + x.ticket_id] = x; }));
  reports.push({
    posted_at: zag(m.ts),
    new_in_window: parentNew,
    reporter: who(m),
    slack_url: link(INC, m.ts),
    text: text.slice(0, 2500),
    replies: reps.map(r => ({ by: who(r), at: zag(r.ts), new_in_window: inWin(r.ts), text: textOf(r).slice(0, 1200), slack_url: link(INC, r.ts, m.ts) })),
    tickets: Object.keys(tk).map(k => tk[k])
  });
});
reports.sort((x, y) => String(x.posted_at).localeCompare(String(y.posted_at)));
if (winAlerts.length > 60) gaps.push('More than 60 error alerts in the window; only the first 60 executions were digested.');
return [{ json: { window: w, win_alerts: winAlerts, hist: hist, reports: reports, gaps: gaps } }];

const b = $('Build incidents').first().json;
const items = (b.win_alerts || []).filter(a => a.execution_id).slice(0, 60).map(a => ({ json: { workflow_id: a.workflow_id, execution_id: a.execution_id } }));
return items.length ? items : [{ json: { workflow_id: '', execution_id: '' } }];

const b = $('Build incidents').first().json;
const digests = $input.all().map(i => i.json).filter(d => d && d.execution_id);
const byExec = {};
(b.win_alerts || []).forEach(a => { byExec[a.execution_id] = a; });
const brandSub = {};
digests.forEach(d => { const a = byExec[d.execution_id]; if (a && a.brand && d.ticket && d.ticket.subdomain) brandSub[a.brand] = d.ticket.subdomain; });
const tk = {};
digests.forEach(d => {
  if (!d.ticket || !d.ticket.ticket_id) return;
  const a = byExec[d.execution_id];
  const sub = d.ticket.subdomain || (a ? brandSub[a.brand] : null);
  if (sub) tk[sub + '/' + d.ticket.ticket_id] = { subdomain: sub, ticket_id: String(d.ticket.ticket_id) };
});
(b.reports || []).forEach(r => (r.tickets || []).forEach(t => { tk[t.subdomain + '/' + t.ticket_id] = { subdomain: t.subdomain, ticket_id: String(t.ticket_id) }; }));
const list = Object.keys(tk).map(k => tk[k]).slice(0, 80);
return list.length ? list.map(t => ({ json: t })) : [{ json: { subdomain: '', ticket_id: '' } }];

const b = $('Build incidents').first().json;
const BASE = 'https://efuturemedia.app.n8n.cloud';
const gaps = (b.gaps || []).slice();
const digests = {};
$('Digest executions').all().forEach(i => { const d = i.json; if (d && d.execution_id) digests[d.execution_id] = d; });
const tickets = {};
$('Lookup tickets').all().forEach(i => { const t = i.json; if (t && t.ticket_id) tickets[t.subdomain + '/' + t.ticket_id] = t; });
const ms = s => { const t = new Date(s).getTime(); return isNaN(t) ? 0 : t; };
const alerts = b.win_alerts || [];
const byExec = {};
alerts.forEach(a => { byExec[a.execution_id] = a; a.digest = digests[a.execution_id] || null; });
alerts.forEach(a => {
  const d = a.digest;
  const p = d && d.parent_execution ? d.parent_execution.execution_id : null;
  if (p && byExec[p] && p !== a.execution_id) a.parent_alert = p;
});
alerts.forEach(a => {
  const d = a.digest;
  const s = d && d.error && d.error.failed_sub_execution ? d.error.failed_sub_execution.execution_id : null;
  if (s && byExec[s] && !byExec[s].parent_alert && s !== a.execution_id) byExec[s].parent_alert = a.execution_id;
});
alerts.forEach(a => {
  if (a.parent_alert) return;
  if (a.digest && a.digest.available) return;
  const cand = alerts.filter(c => c !== a && c.is_caller && c.error_message === a.error_message && Math.abs(Number(c.ts) - Number(a.ts)) <= 3 && Number(c.execution_id) < Number(a.execution_id) && !alerts.some(x => x.parent_alert === c.execution_id));
  if (cand.length) a.parent_alert = cand[cand.length - 1].execution_id;
});
const hasChild = {};
alerts.forEach(a => { if (a.parent_alert) hasChild[a.parent_alert] = true; });
const leaves = alerts.filter(a => !hasChild[a.execution_id]);
const normNode = n => String(n || '').replace(/[0-9]+$/, '').trim();
const sig = a => a.workflow_type + ' | ' + normNode(a.errored_node) + ' | ' + a.error_message;
const brandSub = {};
alerts.forEach(a => { const t = a.digest && a.digest.ticket; if (t && t.subdomain && a.brand) brandSub[a.brand] = t.subdomain; });
const ticketFor = chain => {
  for (const a of chain) {
    const t = a.digest && a.digest.ticket;
    if (t && t.ticket_id) return { subdomain: t.subdomain || brandSub[a.brand] || null, ticket_id: String(t.ticket_id) };
  }
  return null;
};
const ticketState = (tk, sinceIso) => {
  if (!tk) return null;
  const url = tk.subdomain ? 'https://' + tk.subdomain + '.zendesk.com/agent/tickets/' + tk.ticket_id : null;
  const L = tickets[tk.subdomain + '/' + tk.ticket_id];
  if (!L) return { ticket_id: tk.ticket_id, ticket_url: url, lookup: 'not available' };
  const since = ms(sinceIso);
  const after = (L.timeline || []).filter(e => ms(e.at) >= since - 60000);
  return {
    ticket_id: tk.ticket_id,
    ticket_url: L.ticket_url,
    status: L.status,
    subject: L.subject,
    allow_automation: L.key_fields ? L.key_fields['Allow automation'] : null,
    category: L.key_fields ? L.key_fields['Category'] : null,
    tags: L.tags,
    last_automation_action_at: L.automation ? L.automation.last_action_at : null,
    events_since_error: after.slice(-8),
    lookup_errors: L.errors && L.errors.length ? L.errors : undefined
  };
};
const incidents = leaves.map(leaf => {
  const chain = [leaf];
  let cur = leaf;
  let guard = 0;
  while (cur.parent_alert && byExec[cur.parent_alert] && guard < 10) { cur = byExec[cur.parent_alert]; chain.push(cur); guard += 1; }
  return { root: leaf, chain: chain };
});
const groups = {};
incidents.forEach(inc => { const s = sig(inc.root); if (!groups[s]) groups[s] = []; groups[s].push(inc); });
const hist = b.hist || {};
const detail = d => ({
  execution_url: d.execution_url,
  workflow_name: d.workflow_name,
  workflow_url: d.workflow_url,
  available: d.available,
  note: d.note,
  status: d.status,
  started_at: d.started_at,
  error: d.error,
  errored_node_parameters_ran: d.errored_node_parameters_ran,
  errored_node_in_draft: d.errored_node_in_draft,
  errored_node_parameters_draft: d.errored_node_parameters_draft,
  has_unpublished_draft: d.has_unpublished_draft,
  errored_node_input: d.errored_node_input,
  trigger: d.trigger,
  path_tail: d.path_tail,
  zendesk_webhook: d.zendesk_webhook
});
const groupList = Object.keys(groups).map(s => {
  const incs = groups[s].sort((x, y) => Number(x.root.ts) - Number(y.root.ts));
  const r0 = incs[0].root;
  const brands = [];
  incs.forEach(i => { if (i.root.brand && brands.indexOf(i.root.brand) < 0) brands.push(i.root.brand); });
  let maxHr = 0;
  incs.forEach(i => {
    const t0 = Number(i.root.ts);
    const n = incs.filter(j => Number(j.root.ts) >= t0 && Number(j.root.ts) < t0 + 3600).length;
    if (n > maxHr) maxHr = n;
  });
  const reps = incs.map(i => i.root.digest).filter(d => d && d.available).slice(0, 2);
  return {
    signature: s,
    workflow_type: r0.workflow_type,
    errored_node: r0.errored_node,
    error_message: r0.error_message,
    brands: brands,
    incidents_count: incs.length,
    alerts_count: incs.reduce((n, i) => n + i.chain.length, 0),
    first_at: r0.time,
    last_at: incs[incs.length - 1].root.time,
    max_incidents_within_60_min: maxHr,
    recurring: hist[s] ? hist[s] : { prior_6_days_alerts: 0 },
    representative_detail: reps.map(detail),
    incidents: incs.map(i => {
      const a = i.root;
      const d = a.digest || {};
      return {
        time: a.time,
        brand: a.brand,
        workflow_name: a.workflow_name,
        workflow_url: BASE + '/workflow/' + a.workflow_id,
        execution_url: BASE + '/workflow/' + a.workflow_id + '/executions/' + a.execution_id,
        slack_url: a.slack_url,
        execution_available: d.available === undefined ? null : d.available,
        http_code: d.error ? d.error.http_code : null,
        api_response: d.error && d.error.api_response ? String(d.error.api_response).slice(0, 300) : null,
        callers: i.chain.slice(1).map(c => ({ workflow_name: c.workflow_name, workflow_url: BASE + '/workflow/' + c.workflow_id, execution_url: BASE + '/workflow/' + c.workflow_id + '/executions/' + c.execution_id, errored_node: c.errored_node, slack_url: c.slack_url })),
        thread_notes: a.notes && a.notes.length ? a.notes : undefined,
        ticket: ticketState(ticketFor(i.chain), new Date(Number(a.ts) * 1000).toISOString())
      };
    })
  };
}).sort((x, y) => y.incidents_count - x.incidents_count);
alerts.forEach(a => {
  if (!a.digest) gaps.push('No digest for execution ' + BASE + '/workflow/' + a.workflow_id + '/executions/' + a.execution_id);
  else if (a.digest.available === false) gaps.push('Execution pruned or unavailable: ' + BASE + '/workflow/' + a.workflow_id + '/executions/' + a.execution_id);
  else if (!ticketFor([a]) && !a.is_caller) gaps.push('No ticket found in execution ' + BASE + '/workflow/' + a.workflow_id + '/executions/' + a.execution_id);
});
Object.keys(tickets).forEach(k => { const t = tickets[k]; if (t.errors && t.errors.length) gaps.push('Ticket lookup issue for ' + t.ticket_url + ': ' + t.errors.join('; ')); });
const reports = (b.reports || []).map(r => ({
  posted_at: r.posted_at,
  reporter: r.reporter,
  slack_url: r.slack_url,
  new_in_window: r.new_in_window,
  text: r.text,
  replies: r.replies,
  tickets: r.tickets.map(t => tickets[t.subdomain + '/' + t.ticket_id] || { ticket_url: 'https://' + t.subdomain + '.zendesk.com/agent/tickets/' + t.ticket_id, lookup: 'not available' })
}));
return [{ json: {
  window: { date: b.window.date, zone: b.window.zone, start_utc: b.window.start_iso, end_utc: b.window.end_iso },
  counts: { error_alerts: alerts.length, incidents: incidents.length, error_groups: groupList.length, cs_reports: reports.length, tickets_looked_up: Object.keys(tickets).length },
  error_groups: groupList,
  cs_reports: reports,
  gaps: gaps,
  sources: { errors_channel: 'https://futuremedia-world.enterprise.slack.com/archives/C0ABPEER1MF', incidents_channel: 'https://futuremedia-world.enterprise.slack.com/archives/C0A44SWQVHD' },
  generated_at: new Date().toISOString()
} }];
